function solve(n, arestas) {
    const adj = Array.from({ length: n }, () => []);
    const indeg = new Array(n).fill(0);

    for (const [a, b] of arestas) {
        adj[a].push(b);
        indeg[b]++;
    }

    // Min-heap (priority queue)
    const heap = [];
    const push = (val) => {
        heap.push(val);
        let i = heap.length - 1;
        while (i > 0) {
            const parent = (i - 1) >> 1;
            if (heap[parent] > heap[i]) {
                [heap[parent], heap[i]] = [heap[i], heap[parent]];
                i = parent;
            } else break;
        }
    };

    const pop = () => {
        const top = heap[0];
        const end = heap.pop();
        if (heap.length > 0) {
            heap[0] = end;
            let i = 0;
            const len = heap.length;
            while (true) {
                let smallest = i;
                const left = 2 * i + 1;
                const right = 2 * i + 2;
                if (left < len && heap[left] < heap[smallest]) smallest = left;
                if (right < len && heap[right] < heap[smallest]) smallest = right;
                if (smallest !== i) {
                    [heap[i], heap[smallest]] = [heap[smallest], heap[i]];
                    i = smallest;
                } else break;
            }
        }
        return top;
    };

    const result = [];
    for (let i = 0; i < n; i++) {
        if (indeg[i] === 0) push(i);
    }

    while (heap.length > 0) {
        const u = pop();
        result.push(u);
        for (const v of adj[u]) {
            indeg[v]--;
            if (indeg[v] === 0) push(v);
        }
    }

    return result.length === n ? result : null;
}
